1348: fn substitute_action_item(item: ActionItem, replacements: &HashMap<String, Expr>) -> ActionItem {
1349:     let indexed = IndexedReplacements::new();
1350:     match item {
1351:         ActionItem::Requires(expr, span) => {
1352:             ActionItem::Requires(substitute(expr, replacements, &indexed), span)
1353:         }
1354:         ActionItem::Ensures(expr, span) => {
1355:             ActionItem::Ensures(substitute(expr, replacements, &indexed), span)
1356:         }
1357:         ActionItem::Let(name, expr, span) => {
1358:             ActionItem::Let(name, substitute(expr, replacements, &indexed), span)
1359:         }
1360:         ActionItem::Statement(statement) => {
1361:             ActionItem::Statement(substitute_statement(statement, replacements))
1362:         }
1363:     }
1364: }
