1366: fn substitute_statement(statement: Statement, replacements: &HashMap<String, Expr>) -> Statement {
1367:     let indexed = IndexedReplacements::new();
1368:     match statement {
1369:         Statement::Assign {
1370:             target,
1371:             value,
1372:             span,
1373:         } => Statement::Assign {
1374:             target: substitute_lvalue(target, replacements),
1375:             value: substitute(value, replacements, &indexed),
1376:             span,
1377:         },
1378:         Statement::If {
1379:             condition,
1380:             then_statements,
1381:             else_statements,
1382:             span,
1383:         } => Statement::If {
1384:             condition: substitute(condition, replacements, &indexed),
1385:             then_statements: then_statements
1386:                 .into_iter()
1387:                 .map(|statement| substitute_statement(statement, replacements))
1388:                 .collect(),
1389:             else_statements: else_statements
1390:                 .into_iter()
1391:                 .map(|statement| substitute_statement(statement, replacements))
1392:                 .collect(),
1393:             span,
1394:         },
1395:         Statement::ForAll {
1396:             binder,
1397:             statements,
1398:             span,
1399:         } => Statement::ForAll {
1400:             binder,
1401:             statements: statements
1402:                 .into_iter()
1403:                 .map(|statement| substitute_statement(statement, replacements))
1404:                 .collect(),
1405:             span,
1406:         },
1407:     }
1408: }
