1410: fn substitute_lvalue(lvalue: LValue, replacements: &HashMap<String, Expr>) -> LValue {
1411:     match lvalue {
1412:         LValue::Index(name, expr) => LValue::Index(
1413:             name,
1414:             substitute(expr, replacements, &IndexedReplacements::new()),
1415:         ),
1416:         LValue::Field(base, field) => {
1417:             LValue::Field(Box::new(substitute_lvalue(*base, replacements)), field)
1418:         }
1419:         lvalue @ LValue::Var(_) => lvalue,
1420:     }
1421: }
